"use strict";
let kept = null;
exports.later = () => {
  kept = { n: 7, tag: "t" };
  return Promise.resolve(kept);
};
exports.laterOf = (value) => {
  kept = value;
  return Promise.resolve(value);
};
exports.fail = () => Promise.reject(new RangeError("nope"));
exports.touch = () => {
  kept.n = 99;
};
exports.same = (value) => value === kept;
